   125	void FrontierFinder::expandFrontier(
   126	    const Eigen::Vector3i& first /* , const int& depth, const int& parent_id */) {
   127	  // std::cout << "depth: " << depth << std::endl;
   128	  auto t1 = ros::Time::now();
   129	
   130	  // Data for clustering
   131	  queue<Eigen::Vector3i> cell_queue;
   132	  vector<Eigen::Vector3d> expanded;
   133	  Vector3d pos;
   134	
   135	  edt_env_->sdf_map_->indexToPos(first, pos);
   136	  expanded.push_back(pos);
   137	  cell_queue.push(first);
   138	  frontier_flag_[toadr(first)] = 1;
   139	
   140	  // Search frontier cluster based on region growing (distance clustering)
   141	  while (!cell_queue.empty()) {
   142	    auto cur = cell_queue.front();
   143	    cell_queue.pop();
   144	    auto nbrs = allNeighbors(cur);
   145	    for (auto nbr : nbrs) {
   146	      // Qualified cell should be inside bounding box and frontier cell not clustered
   147	      int adr = toadr(nbr);
   148	      if (frontier_flag_[adr] == 1 || !edt_env_->sdf_map_->isInBox(nbr) ||
   149	          !(knownfree(nbr) && isNeighborUnknown(nbr)))
   150	        continue;
   151	
   152	      edt_env_->sdf_map_->indexToPos(nbr, pos);
   153	      if (pos[2] < 0.4) continue;  // Remove noise close to ground
   154	      expanded.push_back(pos);
   155	      cell_queue.push(nbr);
   156	      frontier_flag_[adr] = 1;
   157	    }
   158	  }
   159	  if (expanded.size() > cluster_min_) {
   160	    // Compute detailed info
   161	    Frontier frontier;
   162	    frontier.cells_ = expanded;
   163	    computeFrontierInfo(frontier);
   164	    tmp_frontiers_.push_back(frontier);
   165	  }
   166	}
