   168	void FrontierFinder::splitLargeFrontiers(list<Frontier>& frontiers) {
   169	  list<Frontier> splits, tmps;
   170	  for (auto it = frontiers.begin(); it != frontiers.end(); ++it) {
   171	    // Check if each frontier needs to be split horizontally
   172	    if (splitHorizontally(*it, splits)) {
   173	      tmps.insert(tmps.end(), splits.begin(), splits.end());
