   181	bool FrontierFinder::splitHorizontally(const Frontier& frontier, list<Frontier>& splits) {
   182	  // Split a frontier into small piece if it is too large
   183	  auto mean = frontier.average_.head<2>();
   184	  bool need_split = false;
   185	  for (auto cell : frontier.filtered_cells_) {
   186	    if ((cell.head<2>() - mean).norm() > cluster_size_xy_) {
   187	      need_split = true;
   188	      break;
   189	    }
   190	  }
   191	  if (!need_split) return false;
   192	
   193	  // Compute principal component
   194	  // Covariance matrix of cells
   195	  Eigen::Matrix2d cov;
   196	  cov.setZero();
   197	  for (auto cell : frontier.filtered_cells_) {
   198	    Eigen::Vector2d diff = cell.head<2>() - mean;
   199	    cov += diff * diff.transpose();
   200	  }
   201	  cov /= double(frontier.filtered_cells_.size());
   202	
   203	  // Find eigenvector corresponds to maximal eigenvector
   204	  Eigen::EigenSolver<Eigen::Matrix2d> es(cov);
   205	  auto values = es.eigenvalues().real();
   206	  auto vectors = es.eigenvectors().real();
   207	  int max_idx;
   208	  double max_eigenvalue = -1000000;
   209	  for (int i = 0; i < values.rows(); ++i) {
   210	    if (values[i] > max_eigenvalue) {
   211	      max_idx = i;
   212	      max_eigenvalue = values[i];
   213	    }
   214	  }
   215	  Eigen::Vector2d first_pc = vectors.col(max_idx);
   216	  std::cout << "max idx: " << max_idx << std::endl;
   217	  std::cout << "mean: " << mean.transpose() << ", first pc: " << first_pc.transpose() << std::endl;
   218	
   219	  // Split the frontier into two groups along the first PC
   220	  Frontier ftr1, ftr2;
   221	  for (auto cell : frontier.cells_) {
   222	    if ((cell.head<2>() - mean).dot(first_pc) >= 0)
   223	      ftr1.cells_.push_back(cell);
   224	    else
   225	      ftr2.cells_.push_back(cell);
   226	  }
   227	  computeFrontierInfo(ftr1);
   228	  computeFrontierInfo(ftr2);
   229	
   230	  // Recursive call to split frontier that is still too large
   390	  // Compute downsampled cluster
   391	  downsample(ftr.cells_, ftr.filtered_cells_);
   392	}
