   596	void FrontierFinder::findViewpoints(
   597	    const Vector3d& sample, const Vector3d& ftr_avg, vector<Viewpoint>& vps) {
   598	  if (!edt_env_->sdf_map_->isInBox(sample) ||
   599	      edt_env_->sdf_map_->getInflateOccupancy(sample) == 1 || isNearUnknown(sample))
   600	    return;
   601	
   602	  double left_angle_, right_angle_, vertical_angle_, ray_length_;
   603	
   604	  // Central yaw is determined by frontier's average position and sample
   605	  auto dir = ftr_avg - sample;
   606	  double hc = atan2(dir[1], dir[0]);
   607	
   608	  vector<int> slice_gains;
   609	  // Evaluate info gain of different slices
   610	  for (double phi_h = -M_PI_2; phi_h <= M_PI_2 + 1e-3; phi_h += M_PI / 18) {
   611	    // Compute gain of one slice
   612	    int gain = 0;
   613	    for (double phi_v = -vertical_angle_; phi_v <= vertical_angle_; phi_v += vertical_angle_ / 3) {
   614	      // Find endpoint of a ray
   615	      Vector3d end;
   616	      end[0] = sample[0] + ray_length_ * cos(phi_v) * cos(hc + phi_h);
   617	      end[1] = sample[1] + ray_length_ * cos(phi_v) * sin(hc + phi_h);
   618	      end[2] = sample[2] + ray_length_ * sin(phi_v);
   619	
   620	      // Do raycasting to check info gain
   621	      Vector3i idx;
   622	      raycaster_->input(sample, end);
   623	      while (raycaster_->nextId(idx)) {
   624	        // Hit obstacle, stop the ray
   625	        if (edt_env_->sdf_map_->getInflateOccupancy(idx) == 1 || !edt_env_->sdf_map_->isInBox(idx))
   626	          break;
   627	        // Count number of unknown cells
   628	        if (edt_env_->sdf_map_->getOccupancy(idx) == SDFMap::UNKNOWN) ++gain;
   629	      }
   630	    }
   631	    slice_gains.push_back(gain);
   632	  }
   633	
   634	  // Sum up slices' gain to get different yaw's gain
   635	  vector<pair<double, int>> yaw_gains;
   636	  for (int i = 0; i < 6; ++i)  // [-90,-10]-> [10,90], delta_yaw = 20, 6 groups
   637	  {
   638	    double yaw = hc - M_PI_2 + M_PI / 9.0 * i + right_angle_;
   639	    int gain = 0;
   640	    for (int j = 2 * i; j < 2 * i + 9; ++j)  // 80 degree hFOV, 9 slices
   641	      gain += slice_gains[j];
   642	    yaw_gains.push_back(make_pair(yaw, gain));
   643	  }
   644	
   645	  // Get several yaws with highest gain
   646	  vps.clear();
   647	  sort(
   648	      yaw_gains.begin(), yaw_gains.end(),
   649	      [](const pair<double, int>& p1, const pair<double, int>& p2) {
   650	        return p1.second > p2.second;
   651	      });
   652	  for (int i = 0; i < 3; ++i) {
   653	    if (yaw_gains[i].second < min_visib_num_) break;
   654	    Viewpoint vp = { sample, yaw_gains[i].first, yaw_gains[i].second };
   655	    while (vp.yaw_ < -M_PI)
   656	      vp.yaw_ += 2 * M_PI;
   657	    while (vp.yaw_ > M_PI)
   658	      vp.yaw_ -= 2 * M_PI;
   659	    vps.push_back(vp);
   660	  }
   661	}
