   663	// Sample viewpoints around frontier's average position, check coverage to the frontier cells
   664	void FrontierFinder::sampleViewpoints(Frontier& frontier) {
   665	  // Evaluate sample viewpoints on circles, find ones that cover most cells
   666	  for (double rc = candidate_rmin_, dr = (candidate_rmax_ - candidate_rmin_) / candidate_rnum_;
   667	       rc <= candidate_rmax_ + 1e-3; rc += dr)
   668	    for (double phi = -M_PI; phi < M_PI; phi += candidate_dphi_) {
   669	      Vector3d sample_pos = frontier.average_ + rc * Vector3d(cos(phi), sin(phi), 0);
   670	      if (force_viewpoint_z_) sample_pos[2] = viewpoint_z_;
   671	
   672	      // Qualified viewpoint is in bounding box and in safe region
   673	      if (!edt_env_->sdf_map_->isInBox(sample_pos) ||
   674	          edt_env_->sdf_map_->getInflateOccupancy(sample_pos) == 1 || isNearUnknown(sample_pos))
   675	        continue;
   676	
   677	      // Compute average yaw
   678	      auto& cells = frontier.filtered_cells_;
   679	      Eigen::Vector3d ref_dir = (cells.front() - sample_pos).normalized();
   680	      double avg_yaw = 0.0;
   681	      for (int i = 1; i < cells.size(); ++i) {
   682	        Eigen::Vector3d dir = (cells[i] - sample_pos).normalized();
   683	        double yaw = acos(dir.dot(ref_dir));
   684	        if (ref_dir.cross(dir)[2] < 0) yaw = -yaw;
   685	        avg_yaw += yaw;
   686	      }
   687	      avg_yaw = avg_yaw / cells.size() + atan2(ref_dir[1], ref_dir[0]);
   688	      wrapYaw(avg_yaw);
   689	      // Compute the fraction of covered and visible cells
   690	      int visib_num = countVisibleCells(sample_pos, avg_yaw, cells);
   691	      if (visib_num > min_visib_num_) {
   692	        Viewpoint vp = { sample_pos, avg_yaw, visib_num };
   693	        frontier.viewpoints_.push_back(vp);
   694	        // int gain = findMaxGainYaw(sample_pos, frontier, sample_yaw);
   695	      }
   696	      // }
   697	    }
