   178	void MapROS::proessDepthImage() {
   179	  proj_points_cnt = 0;
   180	
   181	  uint16_t* row_ptr;
   182	  int cols = depth_image_->cols;
   183	  int rows = depth_image_->rows;
   184	  double depth;
   185	  Eigen::Matrix3d camera_r = camera_q_.toRotationMatrix();
   186	  Eigen::Vector3d pt_cur, pt_world;
   187	  const double inv_factor = 1.0 / k_depth_scaling_factor_;
   188	
   189	  for (int v = depth_filter_margin_; v < rows - depth_filter_margin_; v += skip_pixel_) {
   190	    row_ptr = depth_image_->ptr<uint16_t>(v) + depth_filter_margin_;
   191	    for (int u = depth_filter_margin_; u < cols - depth_filter_margin_; u += skip_pixel_) {
   192	      depth = (*row_ptr) * inv_factor;
   193	      row_ptr = row_ptr + skip_pixel_;
   194	
   195	      // // filter depth
   196	      // if (depth > 0.01)
   197	      //   depth += rand_noise_(eng_);
   198	
   199	      // TODO: simplify the logic here
   200	      if (*row_ptr == 0 || depth > depth_filter_maxdist_)
   201	        depth = depth_filter_maxdist_;
   202	      else if (depth < depth_filter_mindist_)
   203	        continue;
   204	
   205	      pt_cur(0) = (u - cx_) * depth / fx_;
   206	      pt_cur(1) = (v - cy_) * depth / fy_;
   207	      pt_cur(2) = depth;
   208	      pt_world = camera_r * pt_cur + camera_pos_;
   209	      auto& pt = point_cloud_.points[proj_points_cnt++];
   210	      pt.x = pt_world[0];
   211	      pt.y = pt_world[1];
   212	      pt.z = pt_world[2];
   213	    }
   214	  }
   215	
   216	  publishDepth();
   217	}
