   208	double Astar::getDiagHeu(const Eigen::Vector3d& x1, const Eigen::Vector3d& x2) {
   209	  double dx = fabs(x1(0) - x2(0));
   210	  double dy = fabs(x1(1) - x2(1));
   211	  double dz = fabs(x1(2) - x2(2));
   212	  double h;
   213	  double diag = min(min(dx, dy), dz);
   214	  dx -= diag;
   215	  dy -= diag;
   216	  dz -= diag;
   217	
   218	  if (dx < 1e-4) {
   219	    h = 1.0 * sqrt(3.0) * diag + sqrt(2.0) * min(dy, dz) + 1.0 * abs(dy - dz);
   220	  }
   221	  if (dy < 1e-4) {
   222	    h = 1.0 * sqrt(3.0) * diag + sqrt(2.0) * min(dx, dz) + 1.0 * abs(dx - dz);
   223	  }
   224	  if (dz < 1e-4) {
   225	    h = 1.0 * sqrt(3.0) * diag + sqrt(2.0) * min(dx, dy) + 1.0 * abs(dx - dy);
   226	  }
   227	  return tie_breaker_ * h;
   228	}
