   868	void FastPlannerManager::calcNextYaw(const double& last_yaw, double& yaw) {
   869	  // round yaw to [-PI, PI]
   870	  double round_last = last_yaw;
   871	  while (round_last < -M_PI) {
   872	    round_last += 2 * M_PI;
   873	  }
   874	  while (round_last > M_PI) {
   875	    round_last -= 2 * M_PI;
   876	  }
   877	
   878	  double diff = yaw - round_last;
   879	  if (fabs(diff) <= M_PI) {
   880	    yaw = last_yaw + diff;
   881	  } else if (diff > M_PI) {
   882	    yaw = last_yaw + diff - 2 * M_PI;
   883	  } else if (diff < -M_PI) {
   884	    yaw = last_yaw + diff + 2 * M_PI;
   885	  }
