   103	        fd_->static_state_ = true;
   104	        clearVisMarker();
   105	      } else if (res == FAIL) {
   106	        // Still in PLAN_TRAJ state, keep replanning
   107	        ROS_WARN("plan fail");
   108	        fd_->static_state_ = true;
   109	      }
   110	      break;
   111	    }
   112	
   113	    case PUB_TRAJ: {
   114	      double dt = (ros::Time::now() - fd_->newest_traj_.start_time).toSec();
   115	      if (dt > 0) {
   116	        bspline_pub_.publish(fd_->newest_traj_);
   117	        fd_->static_state_ = false;
   118	        transitState(EXEC_TRAJ, "FSM");
   119	
   120	        thread vis_thread(&FastExplorationFSM::visualize, this);
   121	        vis_thread.detach();
   122	      }
   123	      break;
   124	    }
   125	
   126	    case EXEC_TRAJ: {
   127	      LocalTrajData* info = &planner_manager_->local_data_;
   128	      double t_cur = (ros::Time::now() - info->start_time_).toSec();
   129	
   130	      // Replan if traj is almost fully executed
   131	      double time_to_end = info->duration_ - t_cur;
   132	      if (time_to_end < fp_->replan_thresh1_) {
   133	        transitState(PLAN_TRAJ, "FSM");
   134	        ROS_WARN("Replan: traj fully executed=================================");
   135	        return;
   136	      }
   137	      // Replan if next frontier to be visited is covered
   138	      if (t_cur > fp_->replan_thresh2_ && expl_manager_->frontier_finder_->isFrontierCovered()) {
   139	        transitState(PLAN_TRAJ, "FSM");
   140	        ROS_WARN("Replan: cluster covered=====================================");
   141	        return;
   142	      }
   143	      // Replan after some time
   144	      if (t_cur > fp_->replan_thresh3_ && !classic_) {
   145	        transitState(PLAN_TRAJ, "FSM");
   146	        ROS_WARN("Replan: periodic call=======================================");
   147	      }
   148	      break;
   149	    }
   150	  }
   151	}
