   153	int FastExplorationFSM::callExplorationPlanner() {
   154	  ros::Time time_r = ros::Time::now() + ros::Duration(fp_->replan_time_);
   155	
   156	  int res = expl_manager_->planExploreMotion(fd_->start_pt_, fd_->start_vel_, fd_->start_acc_,
   157	                                             fd_->start_yaw_);
   158	  classic_ = false;
   159	
   160	  // int res = expl_manager_->classicFrontier(fd_->start_pt_, fd_->start_yaw_[0]);
   161	  // classic_ = true;
   162	
   163	  // int res = expl_manager_->rapidFrontier(fd_->start_pt_, fd_->start_vel_, fd_->start_yaw_[0],
   164	  // classic_);
   165	
   166	  if (res == SUCCEED) {
   167	    auto info = &planner_manager_->local_data_;
   168	    info->start_time_ = (ros::Time::now() - time_r).toSec() > 0 ? ros::Time::now() : time_r;
   169	
   170	    bspline::Bspline bspline;
   171	    bspline.order = planner_manager_->pp_.bspline_degree_;
   172	    bspline.start_time = info->start_time_;
   173	    bspline.traj_id = info->traj_id_;
   174	    Eigen::MatrixXd pos_pts = info->position_traj_.getControlPoint();
   175	    for (int i = 0; i < pos_pts.rows(); ++i) {
   176	      geometry_msgs::Point pt;
   177	      pt.x = pos_pts(i, 0);
   178	      pt.y = pos_pts(i, 1);
   179	      pt.z = pos_pts(i, 2);
   180	      bspline.pos_pts.push_back(pt);
   181	    }
   182	    Eigen::VectorXd knots = info->position_traj_.getKnot();
   183	    for (int i = 0; i < knots.rows(); ++i) {
   184	      bspline.knots.push_back(knots(i));
   185	    }
   186	    Eigen::MatrixXd yaw_pts = info->yaw_traj_.getControlPoint();
   187	    for (int i = 0; i < yaw_pts.rows(); ++i) {
   188	      double yaw = yaw_pts(i, 0);
   189	      bspline.yaw_pts.push_back(yaw);
   190	    }
   191	    bspline.yaw_dt = info->yaw_traj_.getKnotSpan();
   192	    fd_->newest_traj_ = bspline;
   193	  }
   194	  return res;
   195	}
