   351	  fd_->odom_vel_(1) = msg->twist.twist.linear.y;
   352	  fd_->odom_vel_(2) = msg->twist.twist.linear.z;
   353	
   354	  fd_->odom_orient_.w() = msg->pose.pose.orientation.w;
   355	  fd_->odom_orient_.x() = msg->pose.pose.orientation.x;
   356	  fd_->odom_orient_.y() = msg->pose.pose.orientation.y;
   357	  fd_->odom_orient_.z() = msg->pose.pose.orientation.z;
   358	
   359	  Eigen::Vector3d rot_x = fd_->odom_orient_.toRotationMatrix().block<3, 1>(0, 0);
   360	  fd_->odom_yaw_ = atan2(rot_x(1), rot_x(0));
   361	
   362	  fd_->have_odom_ = true;
   363	}
