   267	void FastPlannerManager::planExploreTraj(const vector<Eigen::Vector3d>& tour,
   268	    const Eigen::Vector3d& cur_vel, const Eigen::Vector3d& cur_acc, const double& time_lb) {
   269	  if (tour.empty()) ROS_ERROR("Empty path to traj planner");
   270	
   271	  // Generate traj through waypoints-based method
   272	  const int pt_num = tour.size();
   273	  Eigen::MatrixXd pos(pt_num, 3);
   274	  for (int i = 0; i < pt_num; ++i) pos.row(i) = tour[i];
   275	
   276	  Eigen::Vector3d zero(0, 0, 0);
   277	  Eigen::VectorXd times(pt_num - 1);
   278	  for (int i = 0; i < pt_num - 1; ++i)
   279	    times(i) = (pos.row(i + 1) - pos.row(i)).norm() / (pp_.max_vel_ * 0.5);
   280	
   281	  PolynomialTraj init_traj;
   282	  PolynomialTraj::waypointsTraj(pos, cur_vel, zero, cur_acc, zero, times, init_traj);
   283	
   284	  // B-spline-based optimization
   285	  vector<Vector3d> points, boundary_deri;
   286	  double duration = init_traj.getTotalTime();
   287	  int seg_num = init_traj.getLength() / pp_.ctrl_pt_dist;
   288	  seg_num = max(8, seg_num);
   289	  double dt = duration / double(seg_num);
   290	
   291	  std::cout << "duration: " << duration << ", seg_num: " << seg_num << ", dt: " << dt << std::endl;
   292	
