   294	    points.push_back(init_traj.evaluate(ts, 0));
   295	  boundary_deri.push_back(init_traj.evaluate(0.0, 1));
   296	  boundary_deri.push_back(init_traj.evaluate(duration, 1));
   297	  boundary_deri.push_back(init_traj.evaluate(0.0, 2));
   298	  boundary_deri.push_back(init_traj.evaluate(duration, 2));
   299	
   300	  Eigen::MatrixXd ctrl_pts;
   301	  NonUniformBspline::parameterizeToBspline(
   302	      dt, points, boundary_deri, pp_.bspline_degree_, ctrl_pts);
   303	  NonUniformBspline tmp_traj(ctrl_pts, pp_.bspline_degree_, dt);
   304	
   305	  int cost_func = BsplineOptimizer::NORMAL_PHASE;
   306	  if (pp_.min_time_) cost_func |= BsplineOptimizer::MINTIME;
