   295	void FastExplorationManager::shortenPath(vector<Vector3d>& path) {
   296	  if (path.empty()) {
   297	    ROS_ERROR("Empty path to shorten");
   298	    return;
   299	  }
   300	  // Shorten the tour, only critical intermediate points are reserved.
   301	  const double dist_thresh = 3.0;
   302	  vector<Vector3d> short_tour = { path.front() };
   303	  for (int i = 1; i < path.size() - 1; ++i) {
   304	    if ((path[i] - short_tour.back()).norm() > dist_thresh)
   305	      short_tour.push_back(path[i]);
   306	    else {
   307	      // Add waypoints to shorten path only to avoid collision
   308	      ViewNode::caster_->input(short_tour.back(), path[i + 1]);
   309	      Eigen::Vector3i idx;
   310	      while (ViewNode::caster_->nextId(idx) && ros::ok()) {
   311	        if (edt_environment_->sdf_map_->getInflateOccupancy(idx) == 1 ||
   312	            edt_environment_->sdf_map_->getOccupancy(idx) == SDFMap::UNKNOWN) {
   313	          short_tour.push_back(path[i]);
   314	          break;
   315	        }
   316	      }
   317	    }
   318	  }
   319	  if ((path.back() - short_tour.back()).norm() > 1e-3) short_tour.push_back(path.back());
   320	
   321	  // Ensure at least three points in the path
   322	  if (short_tour.size() == 2)
   323	    short_tour.insert(short_tour.begin() + 1, 0.5 * (short_tour[0] + short_tour[1]));
   324	  path = short_tour;
   325	}
