                               const Eigen::Vector3d& acc, const double dt) {
  Eigen::Matrix3d states2pts;
  states2pts << 1.0, -dt, (1.0 / 3.0) * dt * dt, 1.0, 0.0, -(1.0 / 6.0) * dt * dt, 1.0, dt,
