      path_dir /= path_norm;
      const double forward_speed = velocity_xy.dot(path_dir);
      const double cos_angle = forward_speed / speed_xy;
      const double angle_threshold =
          pp_.start_velocity_conflict_angle_deg_ * M_PI / 180.0;

      if (cos_angle < cos(angle_threshold)) {
        start_vel = cur_vel;
        start_vel[0] = max(0.0, forward_speed) * path_dir[0];
        start_vel[1] = max(0.0, forward_speed) * path_dir[1];
        ROS_WARN("project start velocity: angle=%.1f deg, current=(%.3f, %.3f), "
                 "used=(%.3f, %.3f)",
                 acos(max(-1.0, min(1.0, cos_angle))) * 180.0 / M_PI,
                 cur_vel[0], cur_vel[1], start_vel[0], start_vel[1]);
      }
    }
  }

  geometry_msgs::TwistStamped current_velocity_msg;
  current_velocity_msg.header.stamp = ros::Time::now();
  current_velocity_msg.header.frame_id = "world";
